item.content:encoded:
.home-course .learndash-pager,
.home-course .entry-content{
	display:none;
}

.main-navigation &gt; ul{
	text-align:center;
}
.main-navigation ul li &gt; ul.sub-menu{
	text-align:left;
}
.reign-full_width_no_title .content-wrapper{
	padding:0 15px;
}
.fa{
        font-family: "FontAwesome" !important;
}
.fab {
    font-family: "Font Awesome 5 Brands" !important;
}
.far, .fas{
	    font-family: "Font Awesome 5 Free" !important;
}

.widget.earned_user_achievements_class{
	overflow:hidden;
}
.widget.earned_user_achievements_class ul{
	margin:0;
}

.main-navigation > ul{
	text-align:center;
}
.main-navigation ul li > ul.sub-menu{
	text-align:left;
}
.reign-full_width_no_title .content-wrapper{
	padding:0 15px;
}
.fa{
        font-family: "FontAwesome" !important;
}
.fab {
    font-family: "Font Awesome 5 Brands" !important;
}
.far, .fas{
	    font-family: "Font Awesome 5 Free" !important;
}

.widget.earned_user_achievements_class{
	overflow:hidden;
}
.widget.earned_user_achievements_class ul{
	margin:0;
}

